#include "gloo/test/cuda_base_test.h"

namespace gloo {
namespace test {
namespace {

__global__ void waitClocks(const size_t count) {
  clock_t start = clock();
  clock_t offset = 0;
  while (offset < count) {
    offset = clock() - start;
  }
}

} // namespace

void cudaSleep(cudaStream_t stream, size_t clocks) {
  waitClocks<<<1, 1, 0, stream>>>(clocks);
}

int cudaNumDevices() {
  int n = 0;
  CUDA_CHECK(cudaGetDeviceCount(&n));
  return n;
}

} // namespace test
} // namespace gloo

